def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def once(s,a,b):
    assert s.count(a)==1,(a[:100],s.count(a));return s.replace(a,b)
def para(s,start,new):
    i=s.index(start);end=s.find('\n\n',i)
    if end<0:end=len(s)
    return s[:i]+new+s[end:]
def tables(s):return re.findall(r'\\begin\{table\}.*?\\end\{table\}',s,re.S)
def data(t):return t[t.index(r'\midrule')+len(r'\midrule'):t.index(r'\bottomrule')]

